from collections import Counter

class Solution:
    def rearrangeBarcodes(self, barcodes: list[int]) -> list[int]:
        counts = Counter(barcodes)
        sorted_items = sorted(counts.items(), key=lambda x: -x[1])
        n = len(barcodes)
        res = [0] * n
        idx = 0
        for code, freq in sorted_items:
            for _ in range(freq):
                if idx >= n:
                    idx = 1
                res[idx] = code
                idx += 2
        return res

class Solution {
public:
    vector<int> rearrangeBarcodes(vector<int>& barcodes) {
        unordered_map<int, int> counts;
        for (int b : barcodes) counts[b]++;
        vector<pair<int, int>> sorted_items(counts.begin(), counts.end());
        sort(sorted_items.begin(), sorted_items.end(), [](const pair<int, int>& a, const pair<int, int>& b) {
            return a.second > b.second;
        });

        int n = barcodes.size();
        vector<int> res(n, 0);
        int idx = 0;
        for (const auto& item : sorted_items) {
            int code = item.first, freq = item.second;
            for (int k = 0; k < freq; ++k) {
                if (idx >= n) idx = 1;
                res[idx] = code;
                idx += 2;
            }
        }
        return res;
    }
};

class Solution {
    public int[] rearrangeBarcodes(int[] barcodes) {
        Map<Integer, Integer> counts = new HashMap<>();
        for (int b : barcodes) counts.put(b, counts.getOrDefault(b, 0) + 1);
        List<Map.Entry<Integer, Integer>> list = new ArrayList<>(counts.entrySet());
        list.sort((a, b) -> b.getValue().compareTo(a.getValue()));

        int n = barcodes.length;
        int[] res = new int[n];
        int idx = 0;
        for (Map.Entry<Integer, Integer> entry : list) {
            int code = entry.getKey(), freq = entry.getValue();
            for (int k = 0; k < freq; ++k) {
                if (idx >= n) idx = 1;
                res[idx] = code;
                idx += 2;
            }
        }
        return res;
    }
}

var rearrangeBarcodes = function(barcodes) {
    const counts = new Map();
    for (const b of barcodes) counts.set(b, (counts.get(b) || 0) + 1);
    const sortedItems = [...counts.entries()].sort((a, b) => b[1] - a[1]);

    const n = barcodes.length;
    const res = new Array(n).fill(0);
    let idx = 0;
    for (const [code, freq] of sortedItems) {
        for (let k = 0; k < freq; k++) {
            if (idx >= n) idx = 1;
            res[idx] = code;
            idx += 2;
        }
    }
    return res;
};
